import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { trend, pettitt, fdrThreshold, regionalSeries, normalCdf, normalQuantile, select } from "../web/js/stats.js";

// Expected values come from pymannkendall 1.4 and scipy.stats.theilslopes,
// generated by tests/make_reference.py.
const cases = JSON.parse(readFileSync(new URL("./reference.json", import.meta.url)));
const close = (a, b, tol, msg) => assert.ok(Math.abs(a - b) <= tol, `${msg}: ${a} vs ${b}`);

test("normal distribution helpers", () => {
  close(normalCdf(1.959964), 0.975, 1e-6, "cdf");
  close(normalCdf(-3), 0.0013499, 1e-6, "lower tail");
  close(normalQuantile(0.975), 1.959964, 1e-6, "quantile");
  close(normalQuantile(0.001), -3.090232, 1e-5, "quantile tail");
});

test("quickselect matches sorting", () => {
  const values = Array.from({ length: 101 }, (_, i) => Math.sin(i * 12.9898) * 43758.5453 % 1);
  const sorted = [...values].sort((a, b) => a - b);
  for (const k of [0, 13, 50, 100]) assert.equal(select(Float64Array.from(values), values.length, k), sorted[k]);
});

cases.forEach((c, i) => {
  test(`Mann–Kendall and Sen agree with references (case ${i + 1})`, () => {
    const classic = trend(c.x, c.y, { correct: false });
    assert.equal(classic.s, c.s);
    close(classic.varS, c.varS, 1e-9, "var S");
    close(classic.z, c.zClassic, 1e-9, "z");
    close(classic.p, c.pClassic, 1e-6, "p");
    close(classic.tau, c.tau, 1e-12, "tau");
    close(classic.slope, c.slope, 1e-12, "Sen slope");
    close(classic.lower, c.lo, 1e-12, "lower bound");
    close(classic.upper, c.hi, 1e-12, "upper bound");

    const corrected = trend(c.x, c.y);
    close(corrected.z, c.zHR, 1e-6, "Hamed–Rao z");
    close(corrected.p, c.pHR, 1e-6, "Hamed–Rao p");
  });
});

test("missing values are skipped, short series return no result", () => {
  const x = Array.from({ length: 20 }, (_, i) => 2000 + i);
  const y = x.map((v, i) => (i % 5 === 0 ? NaN : v * 0.5));
  const r = trend(x, y);
  assert.equal(r.n, 16);
  close(r.slope, 0.5, 1e-12, "exact slope");
  assert.ok(Number.isNaN(trend(x.slice(0, 7), y.slice(0, 7)).slope));
});

test("Pettitt finds a step change", () => {
  const x = Array.from({ length: 40 }, (_, i) => 1980 + i);
  const y = x.map((v, i) => (v < 2001 ? 0 : 2) + 0.1 * Math.sin(i * 7));
  const r = pettitt(x, y);
  assert.equal(r.lastBefore, 2000);
  assert.equal(r.firstAfter, 2001);
  assert.ok(r.p < 0.001);
  close(r.after - r.before, 2, 0.1, "shift");
});

test("Benjamini–Hochberg threshold", () => {
  // Classic example: with q = 0.05 the first four are discoveries.
  const p = [0.01, 0.011, 0.012, 0.013, 0.2, 0.3, 0.5, 0.7, 0.9, 0.95];
  assert.equal(fdrThreshold(p, 0.05), 0.013);
  assert.equal(fdrThreshold([0.5, 0.6, NaN], 0.05), 0);
});

test("regional mean weights by latitude and respects coverage", () => {
  // Two latitudes (0° and 60°), one longitude, two years.
  const fill = -32768;
  const cube = Int16Array.from([100, 200, 100, fill]);
  const series = regionalSeries(cube, 2, [0, 1], [0, 60], 1, fill, 0.01);
  close(series[0], (1 * 1 + 2 * 0.5) / 1.5, 1e-9, "weighted mean");
  assert.ok(Number.isNaN(series[1]), "year below coverage is missing");
  const loose = regionalSeries(cube, 2, [0, 1], [0, 60], 1, fill, 0.01, 0.5);
  close(loose[1], 1, 1e-9, "lower coverage threshold");
});
